(x, y, t) => {
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx1 = x+wx1, sy1 = y+wy1;
  const wx2 = Math.sin(sx1*0.025-t*0.15)*8+Math.cos(sy1*0.02+t*0.2)*6;
  const wy2 = Math.cos(sx1*0.02+t*0.18)*8+Math.sin(sy1*0.022-t*0.22)*6;
  const sx = sx1+wx2, sy = sy1+wy2;
  const cx = 240, cy = 120;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,5],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*40,0.14,2.1,0.5],
    [400+Math.cos(t*0.55+2)*70,220+Math.sin(t*0.75+4)*50,0.11,1.8,1.5],
    [200+Math.sin(t*0.38)*90,200+Math.cos(t*0.58+2)*60,0.09,2.4,2.5],
    [300+Math.cos(t*0.42+3)*80,40+Math.sin(t*0.62+1)*70,0.13,1.6,3.5]
  ];
  let aS=0,iS=0,cross=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    cross+=Math.sin(d*f*1.3-t*sp*0.8+ph*2)*0.3;
  }
  const n=src.length,act=aS/n,inh=iS/n,crossN=cross/n;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08+sy*0.06-t*1.5)*0.15+Math.cos(sx*0.05-sy*0.09+t*1.8)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.07+ang*2-t*0.9)*0.2+Math.sin(dist*0.03-ang*6+t*2.1)*0.15;
  const moire=Math.sin(sx*0.3)*Math.sin(sy*0.3)*0.15
    +Math.sin(sx*0.2+sy*0.15+t*0.5)*Math.sin(sx*0.15-sy*0.2-t*0.7)*0.2;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act*0.5-inh*1.1+crossN*0.8+moire*0.5)*1.8);
  const diffused=Math.tanh((r1+r2*0.4)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5
    +Math.sin(sx*0.2-sy*0.12-t*0.8)*0.3)*1.5)*0.3;
  const blend=diffused*0.7+cell*0.2+r2*0.1, v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,40,90],[15,75,115],[20,120,130],[45,160,130],[140,190,100],
    [210,195,70],[230,150,60],[210,100,65],[175,60,70],[120,35,75],[70,20,65],[30,15,55],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i, sf=f*f*(3-2*f);
  const lum=0.8+Math.sin(diffused*Math.PI)*0.2;
  const edge=Math.abs(diffused)>0.7?1.12:1.0;
  const glow=Math.max(0,diffused-0.5)*0.3;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*50)|0)
  ];
}
